```ts
type AnyFn = (...args: any[]) => any;

function debounce<T extends AnyFn>(fn: T, wait: number) {
  let timer: ReturnType<typeof setTimeout> | null = null;

  const debounced = (...args: Parameters<T>) => {
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn(...args);
    }, wait);
  };

  debounced.cancel = () => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  };

  return debounced;
}
```

Usage:

```ts
const search = debounce((q: string) => fetchResults(q), 300);

search("hel");
search("hello"); // only this call actually fires, 300ms later

search.cancel(); // discard a pending call
```

A few notes:

- `Parameters<T>` keeps the argument types of the wrapped function, so you get autocomplete and type checking on `debounced(...)`.
- If you need the return value of `fn`, debouncing is inherently async — either have `fn` return a promise you store, or add a `flush()` that runs the pending call immediately.
- For React, wrap it in `useMemo`/`useRef` so the timer isn't recreated on every render.

